const uint8_t *data = static_cast<const uint8_t*>(buffer);
crc = ~crc;
for (size_t i = 0; i < size; ++i) {
    crc ^= data[i];
    for (int j = 0; j < 8; ++j) {
        uint32_t bit = crc & 1;
        crc >>= 1;
        if (bit) {
            crc ^= 0xEDB88320;
        }
    }
}
return ~crc;
// END_CODE

